with products_by_supplier as (select supplier_id, count(cost) cost_count, count(case when brand = 'Globex' then 1 end) globex_count from products where category = 'Books' group by supplier_id) select s.id, s.rating, pbs.cost_count, pbs.globex_count from suppliers s inner join products_by_supplier pbs on s.id = pbs.supplier_id where pbs.globex_count >= 9 order by pbs.cost_count desc, id limit 10
